/**
 * The landing-page block library: 2,212 bands across 21 industries, FETCHED.
 *
 * The bundled set (`blocks-data.json`, ~300 blocks, 1.6MB) rides along in the
 * editor's JavaScript. This one is 7.8MB and cannot: it ships as static JSON
 * under `public/blocks/`, one file per industry plus a small index, and a
 * category is downloaded the first time somebody opens it. The index is 21
 * rows, so the panel can list every category and its count having fetched
 * almost nothing.
 *
 * Generated by `scripts/gen-landing-blocks.mts`. Each block is self-contained
 * HTML — its own trimmed stylesheet with the design's tokens already resolved
 * to literal values — so `fromHtml` turns it into the same `Template` a bundled
 * block becomes, and it carries the look it was drawn with rather than
 * depending on a theme that does not travel with a fragment.
 */

import { filterCurated } from "./curated"
import { fromHtml, type Template } from "./templates"

interface LandingCategory {
  slug: string
  label: string
  count: number
  bytes: number
}

/** A block as the generator writes it: self-contained HTML plus its name. */
export interface LandingBlock {
  category: string
  name: string
  html: string
}

/**
 * Where the generator writes, as an ABSOLUTE path.
 *
 * Not relative: the editor lives at `/edit/:pageId`, so `blocks/index.json`
 * resolves to `/edit/blocks/index.json` and 404s into the SPA fallback — which
 * answers with index.html, so the fetch succeeds and the JSON parse is what
 * fails. The library would simply never appear, with a syntax error as the
 * only clue.
 */
const BASE = "/blocks"

/**
 * One in-flight promise per URL.
 *
 * Opening a category, closing it and opening it again must not fetch a
 * megabyte twice — and the panel can mount two gallery instances, so this is
 * module-level rather than component state.
 */
const inflight = new Map<string, Promise<unknown>>()

async function getJson<T>(path: string): Promise<T> {
  const existing = inflight.get(path)
  if (existing) return existing as Promise<T>
  const promise = fetch(`${BASE}/${path}`, { headers: { accept: "application/json" } })
    .then((res) => {
      if (!res.ok) throw new Error(`${path}: ${res.status}`)
      return res.json() as Promise<T>
    })
    .catch((e) => {
      // Not cached: a failed fetch should be retried the next time somebody
      // opens the category, not remembered as "this category is empty".
      inflight.delete(path)
      throw e
    })
  inflight.set(path, promise)
  return promise
}

/** The categories and their counts. Cheap enough to call on mount. */
export function landingIndex(): Promise<LandingCategory[]> {
  return getJson<LandingCategory[]>("index.json")
}

/**
 * One industry's blocks, exactly as generated — before curation.
 *
 * For the `/curate` screen, which has to show what has been dropped as well as
 * what has been kept. Everything else wants `landingCategory` below.
 */
export function landingCategoryRaw(slug: string): Promise<LandingBlock[]> {
  return getJson<LandingBlock[]>(`${slug}.json`)
}

/**
 * One industry's blocks, as Templates. Fetched once, then cached.
 *
 * Curated like the bundled set. These used to bypass `filterCurated`
 * altogether, which meant the `/curate` screen governed 304 of the library's
 * 2,516 blocks and silently had no say over the other 2,212 — an owner could
 * export a list and watch the panel ignore it.
 */
export async function landingCategory(slug: string): Promise<Template[]> {
  const raw = await landingCategoryRaw(slug)
  return filterCurated(raw).map((b) => fromHtml(b.category, b.name, b.html))
}
